function CalculateTimeUntilDeath()local time_till_max=Util_GetDifficultyValue(SETTINGS.GetSetting("DIFFICULTY")["hurt_units_on_route"]["time_till_max_damage"])local max_damage=Util_GetDifficultyValue(SETTINGS.GetSetting("DIFFICULTY")["hurt_units_on_route"]["max_damage_per_second"])local time_without_damage=Util_GetDifficultyValue(SETTINGS.GetSetting("DIFFICULTY")["hurt_units_on_route"]["time_without_damage"])local health=1 local time_till_death=time_without_damage+time_till_max local seconds=0 local karmabetweenwaves="Off"if(SETTINGS.GetSetting("DIFFICULTY")["karma_between_waves"]~=nil and SETTINGS.GetSetting("DIFFICULTY")["karma_between_waves"]["hurt_moving_friendly_squads_on_route"]~=nil and Util_GetDifficultyValue(SETTINGS.GetSetting("DIFFICULTY")["karma_between_waves"]["hurt_moving_friendly_squads_on_route"])==true)then local karmabetweenwaves="On"end local karmabetweenwavesmessage="Karma between waves: "..karmabetweenwaves while seconds<=time_till_max do seconds=seconds+1 health=health-((seconds/time_till_max)*max_damage)end time_till_death=round(time_till_death+(health/max_damage),2)local karma_title="Karma difficulty settings:"local karma_without_damage="Time in zone without damage = "..Util_GetDifficultyValue(SETTINGS.GetSetting("DIFFICULTY")["hurt_units_on_route"]["time_without_damage"]).." sec"local karma_death_after="Unit death after = "..time_till_death.." sec"Util_ShowTextOnScreen("karma_title",0.8,0.595,karma_title,180,180,255,1.2,30)Util_ShowTextOnScreen("karma_without_damage",0.82,0.61,karma_without_damage,180,180,255,1.3,30)Util_ShowTextOnScreen("karma_death_after",0.82,0.625,karma_death_after,180,180,255,1.4,30)Util_ShowTextOnScreen("karmabetweenwaves",0.82,0.64,karmabetweenwavesmessage,180,180,255,1.5,30)end
