pMoveGroup)end end Profiler_EndFunction("_SendOrdersToBattleSquads")end function _UpgradeParadrops()Profiler_StartFunction("_UpgradeParadrops")if(#PENDING_PARADROPS==0)then return end local aiGroup=Player_GetSquads(AIPlayer1)local paradropGroup=SGroup_CreateIfNotFound("temp_paratroopers_group")Profiler_Number("_UpgradeParadrops (total)",SGroup_Count(aiGroup))local function removeNonParadropped(groupid,itemindex,itemid)local blueprintName=BP_GetName(Squad_GetBlueprint(itemid))local found=false for i,pendingParadrop in ipairs(PENDING_PARADROPS)do if(pendingParadrop["squadBlueprint"]==blueprintName)then found=true break end end if(found)then SGroup_Add(paradropGroup,itemid)end end SGroup_ForEach(aiGroup,removeNonParadropped)SGroup_Destroy(aiGroup)Profiler_Number("_UpgradeParadrops (filtered)",SGroup_Count(paradropGroup))local function checkNewParadrop(groupid,itemindex,itemid)local found=false for i,paradropSquad in ipairs(SPAWNED_PARADROPS)do if(itemid==paradropSquad)then found=true break end end if(not found)then table.insert(SPAWNED_PARADROPS,itemid)for i,pendingParadrop in ipairs(PENDING_PARADROPS)do local upgrades=pendingParadrop["upgrades"]local slots=pendingParadrop["slots"]local upgradeGroup=SGroup_CreateIfNotFound("temp_paratrooper_group")SGroup_Add(upgradeGroup,itemid)GiveGroupUpgrades(upgradeGroup,upgrades)GiveSquadSlotItems(itemid,slots)SGroup_Destroy(upgradeGroup)table.remove(PENDING_PARADROPS,i)break end end end SGroup_ForEach(paradropGroup,checkNewParadrop)SGroup_Destroy(paradropGroup)Profiler_EndFunction("_UpgradeParadrops")end function TriggerLights(entityGroupName,on,flicker)if(not EGroup_Exists(entityGroupName))then return false end local entityGroup=EGroup_FromName(entityGroupName)if(not flicker)then TriggerLightsDo(entityGroup,states[on])return true end UnsavedTimeRule_AddOneShot(function()TriggerLightsDo(entityGroup,on)end,1.0,1)UnsavedTimeRule_AddOneShot(function()TriggerLightsDo(entityGroup,not on)end,1.2,1)UnsavedTimeRule_AddOneShot(function()T